  Lemma u32r_loop : forall f sz rolling result m1 (x14 x17 : word),
    0 < rolling < 2^(8 * Z.of_nat f) -> 0 <= result < 2^(32 - 8 * Z.of_nat f) -> (f <= 4)%nat ->
    0 <= sz <= zlen pl -> x14 = Z_to_bv 64 (sz + -1) -> INV m1 sz ->
    (forall m2 (y14 y16 y17 : word), INV m2 (snd (draw_loop f pl sz rolling result)) ->
       0 <= fst (draw_loop f pl sz rolling result) < 2^32 ->
       evt psegs POST (STpc 0x1cf04 m2 (Z_to_bv 64 (bv_swrap 32 (fst (draw_loop f pl sz rolling result)))) (Z_to_bv 64 range) (Z_to_bv 64 P) y14 (Z_to_bv 64 (-1)) y16 y17)) ->
